from pathlib import Path
from html import escape

root=Path(__file__).resolve().parent
pages=[]
def table(head,rows):
    return '<table><thead><tr>'+''.join('<th>'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
def note(text):return '<div class="note">'+text+'</div>'
def box(title,text,tone=''):return f'<div class="box {tone}"><h3>{title}</h3><p>{text}</p></div>'
def chain(labels):return '<div class="chain">'+'<span class="arrow">→</span>'.join('<div>'+x+'</div>' for x in labels)+'</div>'
def page(label,title,sub,body):
    n=len(pages)+1
    pages.append(f'<section class="page"><header><b>CargoNest<span>.</span></b><span>REPORTS / VISUAL BLUEPRINT · 06 NOV 2026</span></header><div class="tag">{label}</div><h1>{title}</h1><p class="sub">{sub}</p><div class="body">{body}</div><footer><span>Proposed report layouts · All sample figures are illustrative · Staff workspace</span><b>{n:02d} / 07</b></footer></section>')
def filters(extra=''):
    return '<div class="filters"><span>Date range ▾</span><span>Domestic / International ▾</span><span>Own / External ▾</span><span>Branch / Courier ▾</span>'+extra+'<b>Apply filters</b></div>'
def cards(items):return '<div class="cards">'+''.join(f'<div><small>{label}</small><strong>{value}</strong><em>{hint}</em></div>' for label,value,hint in items)+'</div>'

page('01 / REPORTS HOME','Reports at a glance','Click Reports in the staff menu. Review the company summary, then open the exact report you need.',
    '<div class="screen"><div class="screen-top"><b>WORKSPACE / REPORTS OVERVIEW</b><span>Saved filters · Export summary</span></div>'+filters()+
    cards([('Total bookings','120','Selected booking period'),('Domestic / International','90 / 30','Category split'),('Own / External','70 / 50','Fulfilment split'),('Delivered','86','Booking cohort delivered')])+
    cards([('In progress','28','Active shipments'),('Cancelled','6','Excluded from active stock'),('Freight collected','₹1,00,000','Collection-date basis'),('Freight outstanding','₹24,000','Balance as of selected date')])+
    '<div class="two"><div class="chart"><h3>Shipment categories</h3><div class="bar"><label>Domestic</label><i style="width:75%"></i><b>90</b></div><div class="bar"><label>International</label><i style="width:25%;background:#dfa37a"></i><b>30</b></div><small>Illustration only — not live business data.</small></div><div class="chart"><h3>Fulfilment network</h3><div class="bar"><label>Own logistics</label><i style="width:58%"></i><b>70</b></div><div class="bar"><label>External courier</label><i style="width:42%;background:#dfa37a"></i><b>50</b></div><small>Domestic / international is separate from own / external.</small></div></div>'+
    '<h3 class="section-title">Quick report access</h3><div class="quick"><span>Booking register →</span><span>Own pending stock →</span><span>Courier tracking →</span><span>Collections →</span><span>International →</span></div></div>'+
    chain(['Click a card / quick report','Open filtered report list','Click a shipment','Shipment details & timeline'])+
    note('<b>Dates stay visible:</b> booking counts use booking date; collected money uses collection transaction date; outstanding uses an as-of date. These cards describe different measures and must be labelled accordingly.'))

groups=[
('01','Booking reports',['All bookings','Domestic / International','Branch-wise / Staff-wise','Cancelled bookings']),
('02','Own logistics',['Pending loading','Loading & dispatch','In transit / Received','Pending delivery / Branch stock']),
('03','External couriers',['Courier-wise bookings','Pickup pending / In transit','Delivered / Failed / Return','Confirmation issues / Settlement']),
('04','International',['Shipment register','Country-wise / Own vs external','Documents pending','Clearance / Duties records']),
('05','Collections & accounts',['Paid / To Pay collections','Credit outstanding / FOC','Branch collection summary','Courier payables / Refunds / Margin']),
('06','Delivery & exceptions',['Delivered / Pending delivery','Delayed / Failed attempts','Missing / Damaged','Returns / Cancellation refunds']),
('07','Performance',['Branch performance','Courier performance','Domestic vs International','Own vs External / Staff activity']),
]
page('02 / MENU DRAWING','The complete reports menu','One Reports entry point. Seven sections, with a clear purpose for each.',
    '<div class="root-box">STAFF DASHBOARD → REPORTS → CHOOSE A SECTION</div><div class="tree-line"></div><div class="menu-grid">'+''.join(f'<div class="menu-box"><span>{n}</span><h3>{title}</h3><ul>'+''.join('<li>'+s+'</li>' for s in items)+'</ul></div>' for n,title,items in groups)+'<div class="menu-box guide"><h3>Common actions</h3><ul><li>Filter and search</li><li>Open shipment details</li><li>Export CSV / Excel</li><li>Download PDF / Print</li></ul></div></div>'+
    note('<b>Navigation rule:</b> each menu item opens a named report with relevant filters. Do not create separate copies of the same report just for Domestic, International, Own or External; use category and fulfilment filters where appropriate.')+
    chain(['Reports overview','Select report','Choose dates / filters','View summary + rows','Export or drill down']))

page('03 / REPORT PAGE WIREFRAME','How every report should look','Example: Own logistics → Pending delivery stock. Staff can move from summary to the actual parcel.',
    '<div class="screen"><div class="screen-top"><b>PENDING DELIVERY STOCK</b><span>CSV / Excel &nbsp; | &nbsp; PDF &nbsp; | &nbsp; Print</span></div><p class="caption">Unloaded parcels waiting for delivery. Date basis: stock position as of 06 Nov 2026, 18:00 IST.</p><div class="filters"><span>As-of date & time ▾</span><span>Branch: Vijayawada ▾</span><span>Domestic / International ▾</span><span>Search GRN / LR</span><b>View stock</b></div>'+
    cards([('Shipments','18','Waiting for delivery'),('Packages','24','Physical package quantity'),('To Pay outstanding','₹8,600','Eligible freight remaining'),('Overdue','3','Only where an ETA exists')])+
    table(['Shipment / GRN','Received at branch','Age since receipt','Receiver / Destination','Payment / Outstanding','Action'],[
        ['<b>CN-1101 / GRN-1101</b>','06 Nov · 10:30','7h 30m','Anil · Vijayawada','To Pay / ₹600','<b>Open →</b>'],
        ['CN-1098 / GRN-1098','05 Nov · 16:00','26h','Ravi · Vijayawada','Paid / ₹0','Open →'],
        ['CN-1095 / GRN-1095','04 Nov · 12:00','54h','Meena · Vijayawada','Credit / Party ledger','Open →'],
    ])+'<div class="pagination">Showing 1–3 of 18 shipments <span>← Previous &nbsp; Page 1 of 6 &nbsp; Next →</span></div></div>'+
    '<div class="drill-arrow">↓ Click CN-1101 / Open</div><div class="two">'+box('Shipment details','Sender & receiver → Parcel → Branch route → Freight details → Documents')+box('Movement & actions','Booked → Loaded → In transit → Unloaded<br><b>Current:</b> awaiting delivery confirmation','warm')+'</div>'+
    note('<b>Totals describe the full filtered result.</b> Changing the table page must not change the report totals. Exports should contain the filtered dataset and identify the applied filters, date basis and generation time.'))

page('04 / OPERATIONAL REPORTS','Own logistics vs external couriers','Keep branch stock reports separate from partner tracking reports. Both can contain domestic and international shipments.',
    '<div class="two"><div class="lane"><h2>OWN LOGISTICS</h2>'+chain(['Booked','Loaded','In transit','Unloaded','Delivered'])+
    table(['Report','What staff sees'],[
        ['Pending loading','Booked parcels not yet loaded.'],['Loading & dispatch','Vehicle, driver, dispatch memo and departure.'],['In transit','Dispatched parcels not yet received.'],['Received / Unloading','Destination branch receipt and staff.'],['Pending delivery','Unloaded parcels still at the branch.'],['Branch stock','Physical stock position as of a date/time.'],['Transfers, if enabled','Each intermediate branch handover.'],
    ])+'<div class="mini">Key columns: GRN / LR, origin/destination branch, vehicle, event time, packages, status.</div></div>'+
    '<div class="lane warm"><h2>EXTERNAL COURIER</h2>'+chain(['Booked','Pickup','In transit','Out for delivery','Delivered'])+
    table(['Report','What staff sees'],[
        ['Courier bookings','Selected provider, service and AWB.'],['Pickup pending','Confirmed bookings awaiting pickup.'],['Movement / Tracking','Latest provider event and update time.'],['Delivery outcomes','Delivered, failed attempts and returns.'],['Confirmation issues','Pending / failed carrier booking requests.'],['Partner settlement','Courier cost, paid amount and balance.'],['Tracking freshness','Shipments needing an updated provider status.'],
    ])+'<div class="mini">Key columns: AWB, provider, service, address route, latest event, quote/cost, last update.</div></div></div>'+
    note('<b>Stock is not the same as booking volume.</b> A shipment booked last month may still be in stock today. Stock reports need an as-of view across earlier bookings; they must not silently exclude older pending parcels.')+
    '<div class="two">'+box('Staff click path','Reports → Own logistics → Select stock/movement report → Branch + dates → Parcel list → Shipment history')+box('Partner click path','Reports → External couriers → Select tracking report → Courier + status → AWB list → Provider timeline','warm')+'</div>')

page('05 / INTERNATIONAL REPORTS','An overseas shipment has extra visibility','Show the operational shipment, document readiness and clearance information together, without mixing their values.',
    chain(['Reports','International','Register / Documents / Clearance','Country + fulfilment filters','Open shipment'])+
    '<div class="screen"><div class="screen-top"><b>INTERNATIONAL SHIPMENT REGISTER</b><span>Own overseas + external courier</span></div><div class="filters"><span>Booking date ▾</span><span>Destination country ▾</span><span>Own / External ▾</span><span>Documents / Clearance ▾</span><b>Apply</b></div>'+
    table(['Shipment','Country / Fulfilment','LR / AWB','Declared goods value','Documents','Latest clearance record'],[
        ['CN-INT-201','UAE / Own overseas','LR-DXB-201','AED 500','Complete','Recorded: released'],
        ['CN-INT-202','UK / External','AWB-DEMO-202','GBP 120','Invoice pending','Not yet available'],
        ['CN-INT-203','US / External','AWB-DEMO-203','USD 200','Complete','Recorded: on hold'],
    ])+'</div><div class="three">'+box('Country-wise shipments','Counts, delivery outcomes and active shipments by destination country.')+box('Documents pending','Missing document → responsible staff → follow-up → validated reference.')+box('Clearance / Duties','Recorded events, hold reason, payer and separately recorded duty amounts.','warm')+'</div>'+
    '<div class="three money">'+box('SHIPPING CHARGE','The transport service amount charged / quoted.')+box('DECLARED GOODS VALUE','The declared value of the contents, with currency.')+box('DUTIES / DESTINATION TAXES','Separate recorded charges and payer responsibility.','warm')+'</div>'+
    note('<b>Do not add different currencies together.</b> Show currency per amount. Any base-currency summary needs an explicit conversion rate and date. Document requirements and clearance statuses come from the company/provider workflow; these sample labels are not live compliance checks.')+
    '<p class="caption">Own overseas branches still need international reporting. An own branch is not a reason to hide customs documents or overseas delivery milestones.</p>')

page('06 / COLLECTIONS & ACCOUNTS','Three financial views. Keep them separate.','Customer freight, courier settlement and CargoNest subscription revenue are different ledgers.',
    '<div class="three">'+box('1 · CUSTOMER FREIGHT','Customer charge → Paid / To Pay / Credit / FOC → Actual collections → Outstanding → Refund follow-up')+box('2 · COURIER ACCOUNT','Provider shipment cost → Partner payable → Settlement → Remaining partner balance','warm')+box('3 · PLATFORM SUBSCRIPTION','Company plan payment → Subscription validity → CargoNest platform revenue')+'</div>'+
    '<div class="screen"><div class="screen-top"><b>CUSTOMER FREIGHT & COURIER COST REGISTER</b><span>Sample INR figures only</span></div>'+table(['Shipment','Customer freight','Collected','Outstanding','Courier cost','Courier paid','Courier balance'],[
        ['CN-301','₹600','₹600','₹0','₹400','₹400','₹0'],['CN-302','₹900','₹400','₹500','₹650','₹300','₹350'],['<b>Total</b>','<b>₹1,500</b>','<b>₹1,000</b>','<b>₹500</b>','<b>₹1,050</b>','<b>₹700</b>','<b>₹350</b>'],
    ])+'</div><div class="two">'+box('Collection reports','Paid booking collections · To Pay delivery collections · Credit-party outstanding · FOC register · Branch collection summary')+box('Cost / adjustment reports','Courier payables · Settlements · Refund pending / completed · Shipment margin','warm')+'</div>'+
    table(['Report','Date basis','Click-through'],[
        ['Collections','Actual collection transaction date','Collection → Shipment → Receipt / transaction.'],['Outstanding','Balance as of selected date','Customer / party → Pending shipment ledger.'],['Courier settlement','Settlement transaction date; balance as-of','Courier → Payable shipments → Settlement records.'],['Refunds','Refund transaction date; pending balance as-of','Cancelled shipment → Collection → Refund status.'],['Margin','Defined eligible shipment cohort','Freight less eligible costs and adjustments.'],
    ])+
    note('<b>Illustrative gross spread:</b> ₹1,500 freight − ₹1,050 courier cost = ₹450. This is not net profit: tax treatment, extra costs, discounts, credit notes and refunds need agreed accounting rules. Own logistics margin also needs transport/handling cost allocation.'))

page('07 / PERFORMANCE, EXCEPTIONS & EXPORTS','Reports should lead to an action','Every total needs a definition. Every exception should open the shipment that needs attention.',
    '<div class="two"><div>'+box('PERFORMANCE','Branch-wise · Courier-wise · Staff activity<br>Domestic vs International · Own vs External')+table(['Measure','Definition to show'],[
        ['Delivery success','Delivered / eligible shipments; define cohort.'],['Delivery time','Measured start → delivery; state the period.'],['Delay','Expected delivery vs actual/as-of time.'],['Courier cost','Actual / quoted amount, explicitly labelled.'],
    ])+'</div><div>'+box('EXCEPTIONS','Delayed · Failed attempts · Missing / Damaged<br>Returns · Cancellation / Refund pending','warm')+table(['Information','Purpose'],[
        ['Shipment + current location','Find the affected parcel.'],['Reason + latest event time','Understand the current problem.'],['Owner / branch / courier','Know who follows up.'],['Resolution state','Track open → action → resolved.'],
    ])+'</div></div>'+
    '<h2>Which dates does each report use?</h2>'+table(['Report family','Correct basis','Important behaviour'],[
        ['Bookings','Booking date','Count shipments created during the period.'],['Collections','Collection transaction date','Do not treat all grandTotal values as cash collected.'],['Deliveries','Actual delivery date','Find completions during the period.'],['Stock / Outstanding','As-of date/time','Include unresolved older shipments and balances.'],['Dispatch / Receipt','Relevant operation date','Track movement during the selected period.'],
    ])+
    '<div class="two">'+box('EXPORT HEADER','Report name · Company · Branch/courier filters · Date basis/range · Generated time/timezone · Currency · Totals')+box('ACCESS & DATA RULES','Company-scoped records · Role/branch access · Last tracking update · No ETA = estimate unavailable · No results = clear empty state','warm')+'</div>'+
    note('<b>First release priority:</b> Overview → Booking register → Own pending stock & movement → Courier tracking → International register → Collections / Credit outstanding → Courier settlement → Delivered & exceptions. Advanced profitability and performance comparisons follow after their data rules are agreed.')+
    '<p class="caption">This PDF is a proposed reporting blueprint, not evidence that all screens or calculations already exist in the dummy site or backend.</p>')

css='''@page{size:A4 landscape;margin:0}*{box-sizing:border-box}body{margin:0;background:#e6ebe5;color:#193d3a;font-family:"Segoe UI",Arial,sans-serif;font-size:10pt;-webkit-print-color-adjust:exact;print-color-adjust:exact}.page{position:relative;width:297mm;height:210mm;background:#fff;padding:11mm 15mm 13mm;margin:0 auto 8mm;break-after:page;overflow:hidden}.page:last-child{break-after:auto}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #dbe4d6;padding-bottom:3mm;margin-bottom:4mm}header b{font-size:17pt;letter-spacing:-.7px}header b span{color:#d27a50}header>span{font-size:7pt;letter-spacing:1px;color:#7d8c7b}.tag{font-size:7.5pt;letter-spacing:1.4px;color:#618153;font-weight:bold}h1{font-size:25pt;letter-spacing:-.8px;margin:1.5mm 0 1mm}h2{font-size:12pt;margin:3mm 0 2mm}h3{font-size:10pt;margin:0 0 2mm}p{margin:1mm 0;line-height:1.45}.sub{font-size:10pt;color:#718270;margin:0 0 4mm}.body{font-size:9pt}.screen{border:1px solid #d9e3d4;border-radius:3mm;padding:3mm;background:#fcfdf9}.screen-top{display:flex;justify-content:space-between;font-size:8pt;margin-bottom:2mm;color:#3e6351}.screen-top span{font-size:7pt;color:#82907b}.filters{display:flex;gap:2mm;align-items:center;padding:2mm;background:#edf3e8;border-radius:1mm;margin:2mm 0 3mm}.filters span{background:#fff;border:1px solid #dce6d6;border-radius:1mm;padding:2mm 3mm;font-size:7.5pt;flex:1;white-space:nowrap}.filters b{background:#286454;color:#fff;padding:2.5mm 4mm;border-radius:1mm;font-size:7.5pt;white-space:nowrap}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:2.5mm;margin:2.5mm 0}.cards>div{border:1px solid #dce5d5;background:#fff;padding:2.5mm 3mm;border-radius:2mm}.cards small{font-size:7.5pt;color:#72846e;display:block}.cards strong{font-size:18pt;display:block;letter-spacing:-.6px;margin:.8mm 0}.cards em{font-size:6.8pt;font-style:normal;color:#85917b}.two,.three{display:grid;gap:3mm;margin:3mm 0}.two{grid-template-columns:1fr 1fr}.three{grid-template-columns:1fr 1fr 1fr}.chart{border:1px solid #dce5d5;border-radius:2mm;padding:3mm;background:#fff}.chart h3{font-size:9pt}.chart small{font-size:6.7pt;color:#85917b}.bar{display:flex;gap:2mm;align-items:center;font-size:7.5pt;margin:3mm 0}.bar label{width:27mm;flex-shrink:0}.bar i{display:block;height:2.7mm;background:#8ea97a;border-radius:2mm;max-width:65%}.bar b{margin-left:auto;font-size:8pt}.quick{display:flex;gap:2mm}.quick span{flex:1;padding:2.5mm;background:#eff4e9;border-radius:1mm;font-size:7.5pt}.section-title{margin-top:3mm}.chain{display:flex;gap:1.5mm;align-items:center;margin:3mm 0}.chain>div{flex:1;text-align:center;border:1px solid #d4e1cb;background:#f1f6eb;padding:2.5mm 2mm;border-radius:1.5mm;font-size:8pt;line-height:1.35}.arrow{color:#879c78;font-size:15pt;flex-shrink:0}.note{background:#f2f6ed;border-left:3px solid #829f6c;padding:2.5mm 3mm;font-size:8.2pt;line-height:1.45;margin:3mm 0}.root-box{background:#1c4941;color:#fff;text-align:center;padding:3mm;border-radius:2mm;font-size:10pt;font-weight:bold}.tree-line{height:5mm;width:1px;background:#a8b99c;margin:auto}.menu-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:4mm}.menu-box{border:1px solid #d5e2ca;border-radius:2mm;padding:4mm;background:#f7faf2;min-height:44mm}.menu-box>span{font-size:7pt;color:#8a9c7d}.menu-box h3{font-size:10pt;margin:1mm 0 3mm}.menu-box ul{padding-left:4mm;margin:0}.menu-box li{font-size:8pt;line-height:1.5;margin-bottom:1.5mm}.guide{background:#faf1e8;border-color:#ecd8c1}.box{border:1px solid #d9e4d0;padding:3mm;border-radius:2mm;background:#f3f7ed}.box p{font-size:8.5pt;line-height:1.5}.box.warm,.warm .box{background:#fcf4e9;border-color:#efdec8}.warm{background:#fdf8f0}.lane{border:1px solid #d9e4d0;padding:3mm;border-radius:2mm}.lane h2{margin:0;font-size:11pt}.lane .chain{margin:2mm 0}.lane .chain>div{font-size:7pt;padding:2mm 1mm}.lane .arrow{font-size:10pt}.lane table{margin:2mm 0}.mini{font-size:8pt;line-height:1.45;padding:2mm;background:#f0f4e9;border-radius:1mm}table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:8pt;margin:2mm 0}th{font-size:7pt;color:#57724d;background:#edf3e7;text-align:left;padding:2mm;line-height:1.3}td{padding:2mm;border-bottom:1px solid #e3eadc;vertical-align:top;line-height:1.4;overflow-wrap:anywhere}tr:nth-child(even)td{background:#f8faf5}.pagination{font-size:7pt;display:flex;justify-content:space-between;color:#84917d;padding-top:2mm}.drill-arrow{text-align:center;font-size:10pt;color:#4b7857;margin:3mm}.caption{font-size:8pt;color:#7d8a73;line-height:1.45}.money .box{border-top:3px solid #8ea97a}.money .box:last-child{border-top-color:#dea278}footer{position:absolute;left:15mm;right:15mm;bottom:6mm;display:flex;justify-content:space-between;border-top:1px solid #dce5d5;padding-top:2mm;color:#86937d;font-size:7pt}footer b{color:#526e4c}@media print{body{background:#fff}.page{margin:0}}'''
css += '''.page{padding:9mm 13mm 12mm}header{margin-bottom:3mm;padding-bottom:2.5mm}h1{font-size:22pt}.sub{margin-bottom:3mm;font-size:9.5pt}.body{font-size:8.5pt}.two,.three{gap:2.5mm;margin:2mm 0}.box,.lane,.chart{padding:2.5mm}.box p{font-size:8pt;line-height:1.4}h2{margin:2mm 0 1.5mm}table{font-size:7.7pt}td,th{padding:1.4mm;line-height:1.3}.note{font-size:8pt;line-height:1.4;margin:2mm 0;padding:2mm 2.5mm}.chain{margin:2mm 0}.chain>div{padding:2mm 1.5mm;font-size:7.7pt}.cards>div{padding:2mm 2.5mm}.cards strong{font-size:16pt}.bar{margin:2mm 0}.filters{margin:1.5mm 0 2mm}.screen{padding:2.5mm}.page:nth-of-type(7) .caption{font-size:7pt}.page:nth-of-type(7) .box p{font-size:7.7pt}.page:nth-of-type(7) .note{font-size:7.7pt}footer{left:13mm;right:13mm}'''
