out=root/'CargoNest-Reports-Visual-Blueprint.html'
out.write_text('<!doctype html><html lang="en"><head><meta charset="UTF-8"><title>CargoNest Reports - Visual Blueprint</title><style>'+css+'</style></head><body>'+''.join(pages)+'</body></html>',encoding='utf-8')
